from pathlib import Path
import json,datetime,hashlib
B=Path(__file__).resolve().parents[2];D=Path(__file__).resolve().parent
now=datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='seconds')
def save(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
cs=[]
selections={23:[('F2','Achalasie : dilatation et effilement distal','DX5','Un cliché statique ne donne pas toute la vidange ; le signe ne remplace ni la manométrie ni l’exclusion d’une pseudo-achalasie.')],24:[('Fig1','TDM : cholestéatome et otite chronique','DX4','Les panneaux correspondent à plusieurs patients et côtés ; une opacité seule ne suffit pas. Ne pas les présenter comme original et copie annotée.'),('Fig4','IRM : diffusion non-EPI et ADC','DX4','La lésion est gauche selon la légende ; diffusion, ADC et fusion sont des acquisitions ou traitements distincts, pas une paire avant/après annotation.'),('Fig7','Pièges de diffusion : greffe et cérumen','DX4','Les panneaux illustrent plusieurs situations postopératoires et côtés ; ne pas annoter le greffon ou le cérumen comme cholestéatome.') ]}
for lot,rows in selections.items():
 folder=B/f'LOT_{lot:03}/illustrations/recherche_web';a=json.loads((folder/'RECHERCHE.json').read_text())['articles'][0];local=[]
 for fid,title,dx,pitfall in rows:
  c=next(dict(f) for f in a['figures'] if f['figure']==fid)
  xml=str((folder/(a['pmcid']+'.xml')).relative_to(B))
  c.update(lot=lot,cibles=[dx],titre=title,piege=pitfall,revue_documentaire=True,decision='retenu_documentaire_sous_reserve_visuelle',preuve_droits_figure=xml+' : licence explicite admissible, légende et absence de crédit tiers séparé relues.',original_acquis=False,pixels_inspectes=False,source_xml=xml)
  cs.append(c);local.append(c)
 save(folder/'SELECTION.json',{'date':now,'candidats':local})
 plan=json.loads((folder/'PLAN.json').read_text());plan['selection']=str((folder/'SELECTION.json').relative_to(B));save(folder/'PLAN.json',plan)
save(D/'CANDIDATS.json',{'date':now,'candidats':cs,'limite':'Sélection documentaire seulement ; aucun pixel clinique acquis, aucune annotation placée, aucune intégration.'})
save(D/'LECTURES.json',{'date':now,'ordre':'Source suisse consultée avant les lectures ciblées des articles accessibles par Europe PMC. Les 33 fenêtres existantes ont été lues ; pas de nouvelle revue clinique exhaustive.','sources':[{'url':'https://www.hug.ch/orl-chirurgie-cervico-faciale/troubles-deglutition','organisme':'HUG, Suisse','passage':'Phases de déglutition et causes des troubles','synthese':'La page distingue les phases orale, pharyngée et œsophagienne et mentionne des causes neurologiques, musculaires et obstructives.','portee':'Contexte pédagogique ; aucune image de cette page copiée.'},{'url':'https://europepmc.org/article/PMC/11913933','auteurs':'Philip Touska ; Steve E J Connor','origine':'European Society of Head and Neck Radiology, recommandations ESR','lecture':'Licence, légendes des huit figures, paragraphes sur faux positifs de diffusion et limites de TDM postopératoire.','synthese':'Les figures proposent anatomie osseuse, lésions et pièges de diffusion. Les changements postopératoires en TDM sont peu spécifiques ; confrontation aux autres séquences nécessaire.','licence':'CC BY 4.0','preuve':'LOT_024/illustrations/recherche_web/PMC11913933.xml'},{'url':'https://europepmc.org/article/PMC/2040141','auteurs':'Farnoosh Farrokhi ; Michael F Vaezi','origine':'Article de revue de 2007 ; source iconographique ancienne, pas recommandation suisse ou européenne actuelle.','lecture':'Licence, deux légendes, paragraphes relatifs au transit baryté et à la pseudo-achalasie.','synthese':'F2 décrit une dilatation œsophagienne avec rétention barytée et effilement distal. Aucun traitement ou classement manométrique ancien transposé.','licence':'CC BY 2.0','preuve':'LOT_023/illustrations/recherche_web/PMC2040141.xml'}],'limites':['Les ouvertures PMC par navigateur web ont retourné un écran de vérification ; la lecture textuelle provient de l’API Europe PMC autorisée.','Pas de nouvelle recherche primaire propre au LOT_022 ; son tri repose sur les fenêtres existantes effectivement lues.','Aucune dose ajoutée, aucune validation AIPS nouvelle, aucun audit indépendant.'],'exclus_recherche':[{'pmcid':'PMC6823561','raison':'NC affichée dans le résultat de recherche ; non acquis.'},{'pmcid':'PMC4531455','raison':'NC-SA affichée ; non acquis.'},{'pmcid':'PMC7028409','raison':'NC-ND affichée ; non acquis.'}]})
